    /** Whether this destination's Passport page is open at the current campaign rank. */
    fun isPlaceUnlocked(place: String, rankIndex: Int, entitled: Boolean): Boolean {
        val wave = Progression.wave[place] ?: return true
        return entitled && wave <= Progression.unlockedMaxWave(rankIndex)
    }

    /** Countries still frosted in the Passport. A free/unlocked destination in a shared
     * country opens that silhouette even if another landmark there belongs to a later wave. */
    fun lockedCountryCodes(rankIndex: Int, entitled: Boolean): Set<String> {
        val unlocked = placeCountry.entries.filter {
            isPlaceUnlocked(it.key, rankIndex, entitled)
        }.mapTo(hashSetOf()) { it.value }
        return placeCountry.values.toSet() - unlocked
    }

