    private val cache = HashMap<String, List<List<Offset>>>()

    /** Filled rings (normalised 0..1) for a country, or empty if none. */
    fun rings(code: String): List<List<Offset>> =
        cache.getOrPut(code) {
            val p = packed[code] ?: return@getOrPut emptyList()
            p.split(';').map { ring ->
                ring.split(' ').map { pt ->
                    val c = pt.split(',')
                    Offset(c[0].toFloat(), c[1].toFloat())
                }
            }
        }
}
